#if UNITY_EDITOR
using System.Linq; using UnityEditor;
namespace UnityCli { public static class BuildSceneStateTool { public static System.Threading.Tasks.ValueTask<BuildSceneMutationResult> Execute(string rawPath, bool enabled, string toolName, UnityCliProjectToolContext ctx) { var path = BuildToolSupport.NormalizeAssetPath(rawPath); if (string.IsNullOrEmpty(path)) throw new UnityCliBridge.BridgeCommandException("E_BUILD_SCENE_PATH_REQUIRED", toolName + " requires path.", "Pass a scene path such as Assets/Scenes/Main.unity."); var list = (EditorBuildSettings.scenes ?? new EditorBuildSettingsScene[0]).ToList(); var index = list.FindIndex(scene => scene.path == path); if (index < 0) throw new UnityCliBridge.BridgeCommandException("E_BUILD_SCENE_NOT_FOUND", "Build Settings does not contain scene: " + path, "Run build.scene.list and pass a listed path."); if (!ctx.DryRun) { list[index] = new EditorBuildSettingsScene(path, enabled); EditorBuildSettings.scenes = list.ToArray(); } return new(new BuildSceneMutationResult { Path = path, Count = list.Count, DryRun = ctx.DryRun }); } } }
#endif
